INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 16, 'theory', 'Квиз: LVM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 0, 'В группе экстент 4 MiB. Какого размера получится том после lvcreate -L 10M?', '["8 MiB", "10 MiB", "12 MiB", "Команда завершится ошибкой: 10 не кратно 4"]', 2, 'Размер тома всегда кратен экстенту, а запрошенный объём округляется вверх: 10 MiB превращаются в три экстента, то есть 12 MiB. Команда пишет об этом сообщение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 1, 'В группе свободно 101 экстент. Сколько экстентов займёт lvcreate -l 50%FREE?', '["50", "51", "49", "101"]', 0, 'При создании тома процент считается целочисленно и округляется вниз: 50,5 даёт 50. При lvextend процент округляется вверх, и та же доля дала бы 51.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 2, 'Область классического снимка заполнилась на 100%. Что происходит со снимком?', '["Он автоматически растёт, пока в группе есть место", "Он превращается в тонкий снимок", "Запись в исходный том блокируется до расширения", "Он становится испорченным (в Attr буква I), чтение даёт ошибки"]', 3, 'Автоматическое расширение работает только если включён порог и запущен dmeventd, а заполненный снимок отключается ядром и отдаёт ошибки. Исходный том продолжает работать.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 3, 'Данные тонкого пула заполнились на 100%. Что делает пул по умолчанию?', '["Удаляет самый старый тонкий том", "Ставит записи в очередь до 60 секунд в ожидании расширения, затем возвращает ошибки", "Сжимает метаданные и продолжает писать", "Молча перезаписывает самые старые блоки"]', 1, 'Так задано поведение whenfull по умолчанию. Поэтому пул расширяют заранее, а порог автоматического расширения ставят ниже 100.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 4, 'Как правильно уменьшить том с ext4?', '["Сначала lvreduce, потом resize2fs", "Уменьшить XFS командой xfs_growfs", "Сначала файловую систему (ext4 размонтированной), потом том; lvreduce -r делает оба шага", "Просто lvreduce: LVM сам переносит данные"]', 2, 'Если отрезать экстенты раньше файловой системы, данные в них будут потеряны. xfs_growfs только расширяет, XFS не уменьшается вовсе.');
